const DETERMINISTIC_FALLBACK_DEPTH: u32 = 2;
const DETERMINISTIC_FALLBACK_MIN_WEIGHT: f64 = 0.2;

fn embedding_unavailable(error: &MindLeakError) -> bool {
    matches!(error, MindLeakError::Model(_) | MindLeakError::Http(_))
}

fn deterministic_recall_fallback(
    engine: &MindLeak,
    query: &str,
    error: &MindLeakError,
) -> Result<Value, String> {
    let graph = engine
        .multi_hop_query(
            query,
            DETERMINISTIC_FALLBACK_DEPTH,
            DETERMINISTIC_FALLBACK_MIN_WEIGHT,
        )
        .map_err(|fallback_error| fallback_error.to_string())?;
    let results = graph.nodes.clone();
    Ok(text_result(&json!({
        "results": results,
        "fallback": {
            "mode": "deterministic_graph",
            "semantic_recall": "unavailable",
            "reason": error.to_string(),
            "advice": "Semantic recall needs an OpenAI-compatible /v1/embeddings endpoint. To use the default, install and start Ollama, then run `ollama pull nomic-embed-text`. Otherwise set MINDLEAK_EMBED_URL, MINDLEAK_EMBED_MODEL, and MINDLEAK_EMBED_API_KEY. Deterministic graph/FTS results are returned instead.",
            "seed": graph.seed,
            "edges": graph.edges,
        }
    })))
}

