#[cfg(test)]
mod tests {
    use mindleak_core::{Result as MindLeakResult, TextEmbedder};
    use mindleak_model::{failure, ModelFailureReason};

    use crate::tools::call;

    use super::*;

    struct UnavailableEmbedder;

    impl TextEmbedder for UnavailableEmbedder {
        fn model(&self) -> &str {
            "nomic-embed-text"
        }

        fn embed(&self, _text: &str) -> MindLeakResult<Vec<f32>> {
            Err(failure(ModelFailureReason::Unreachable, false, "connection refused").into())
        }
    }

    struct KeywordEmbedder;

    impl TextEmbedder for KeywordEmbedder {
        fn model(&self) -> &str {
            "keyword"
        }

        fn embed(&self, text: &str) -> MindLeakResult<Vec<f32>> {
            if text.to_ascii_lowercase().contains("authentication") {
                Ok(vec![1.0, 0.0])
            } else {
                Ok(vec![0.0, 1.0])
            }
        }
    }

    struct InvalidEmbedder;

    impl TextEmbedder for InvalidEmbedder {
        fn model(&self) -> &str {
            "invalid"
        }

        fn embed(&self, _text: &str) -> MindLeakResult<Vec<f32>> {
            Err(MindLeakError::InvalidArgument(
                "invalid recall request".to_string(),
            ))
        }
    }

    fn payload(result: Value) -> Value {
        serde_json::from_str(result["content"][0]["text"].as_str().unwrap()).unwrap()
    }

    #[test]
    fn recall_returns_actionable_deterministic_fallback_when_embeddings_are_unavailable() {
        let engine = MindLeak::open_in_memory()
            .unwrap()
            .with_embedder(Box::new(UnavailableEmbedder));
        engine
            .ingest_file(
                "src/auth.rs",
                "fn authentication_fallback() { validate_session(); }",
            )
            .unwrap();

        let response = call(
            &engine,
            &json!({
                "name": "recall",
                "arguments": { "query": "authentication fallback", "limit": 5 }
            }),
        )
        .unwrap();
        let body = payload(response);

        assert_eq!(body["fallback"]["mode"], "deterministic_graph");
        assert_eq!(body["fallback"]["semantic_recall"], "unavailable");
        assert!(body["fallback"]["reason"]
            .as_str()
            .unwrap()
            .contains("unreachable"));
        let advice = body["fallback"]["advice"].as_str().unwrap();
        assert!(advice.contains("install and start Ollama"));
        assert!(advice.contains("ollama pull nomic-embed-text"));
        assert!(advice.contains("MINDLEAK_EMBED_URL"));
        assert!(body["results"]
            .as_array()
            .unwrap()
            .iter()
            .any(|node| node["id"] == "symbol:src/auth.rs:authentication_fallback"));
        assert!(body["fallback"]["seed"]
            .as_array()
            .unwrap()
            .iter()
            .any(|seed| seed == "symbol:src/auth.rs:authentication_fallback"));
    }

    #[test]
    fn recall_keeps_the_semantic_response_shape_when_embeddings_are_available() {
        let engine = MindLeak::open_in_memory()
            .unwrap()
            .with_embedder(Box::new(KeywordEmbedder));
        engine
            .ingest_file(
                "src/auth.rs",
                "fn authentication_handler() { validate_session(); }",
            )
            .unwrap();
        engine.index_nodes(50).unwrap();

        let response = call(
            &engine,
            &json!({
                "name": "recall",
                "arguments": { "query": "authentication", "limit": 5 }
            }),
        )
        .unwrap();
        let body = payload(response);

        assert_eq!(body.as_object().unwrap().len(), 1);
        assert!(body["results"]
            .as_array()
            .unwrap()
            .iter()
            .any(|hit| hit["id"] == "symbol:src/auth.rs:authentication_handler"));
    }

    #[test]
    fn recall_does_not_hide_non_model_failures_behind_the_fallback() {
        let engine = MindLeak::open_in_memory()
            .unwrap()
            .with_embedder(Box::new(InvalidEmbedder));

        let error = call(
            &engine,
            &json!({ "name": "recall", "arguments": { "query": "anything" } }),
        )
        .unwrap_err();

        assert_eq!(error, "invalid argument: invalid recall request");
    }
}
